-- Objectflix seed data
-- Migration 0003: Seed the BFDIA (Battle for Dream Island Again) show,
-- its first season, and the 28 original episode records
-- (E1-E4, 5a/5c/5d/5e, E6-E25).
--
-- Idempotent by design: fixed UUIDs + INSERT OR IGNORE, so rerunning this
-- migration (or re-applying it) never creates duplicate rows.
--
-- Titles are taken from the .ass subtitle filenames under
-- D:\BFDI\BFDIA ASS SUBTITLES. Full-width punctuation was normalized to
-- ASCII. Episode 19 is stored as "Egg" (plain ASCII) and the API maps it
-- back to its real title (an egg emoji) when serving data.

-- Show: BFDIA
INSERT OR IGNORE INTO shows (id, title, description, image) VALUES
